 [STAThread]static int Main(string[] args){output=args[0];Directory.CreateDirectory(output);Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);Application.ThreadException+=(s,e)=>{uiExceptions++;failures++;File.AppendAllText(Path.Combine(output,"THREAD_EXCEPTIONS.log"),e.Exception.ToString()+Environment.NewLine);};Control.CheckForIllegalCrossThreadCalls=true;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);driver=new Form {Size=new Size(100,100)};Quiet(driver);driver.Shown+=async(s,e)=>await Run();Application.Run(driver);driver.Dispose();return exit;}
